package jed

// The Go deterministic-simulation runner (spec/design/simulation-testing.md). It executes `.sim`
// traces generated by scripts/sim_gen.rb against a Database over the simulated disk
// (sim_disk_test.go), checks the oracles of §8, and writes a transcript the driver
// (scripts/sim.rb) compares across cores.
//
// Run it through the driver (`mise run sim:sweep`, `mise run sim:replay`). Directly:
//
//	JED_SIM_IN=trace.sim JED_SIM_OUT=out/ go test -run '^TestSimRunner$' -count=1 .
//
// JED_SIM_IN is one .sim file, a directory of them, or a file listing trace paths one per line.
// Results append to JED_SIM_RESULTS (default JED_SIM_OUT/go.results.jsonl). With JED_SIM_IMAGES
// set, every image a recovery opens is written to JED_SIM_OUT/<trace>.go.step<N>.img for the
// independent checker (spec/fileformat/verify.rb --check-image).
// Without JED_SIM_IN the test skips, so `go test ./...` is unaffected.

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"hash/fnv"
	"os"
	"path/filepath"
	"runtime/debug"
	"sort"
	"strconv"
	"strings"
	"testing"
)

const (
	simSectorDefault = 64
	simDiskPath      = "sim.jed" // marks the engine durable; the simulated disk is its only storage
)

func TestSimRunner(t *testing.T) {
	in := os.Getenv("JED_SIM_IN")
	if in == "" {
		t.Skip("JED_SIM_IN not set (run through scripts/sim.rb)")
	}
	out := os.Getenv("JED_SIM_OUT")
	if out == "" {
		out = t.TempDir()
	}
	if err := os.MkdirAll(out, 0o755); err != nil {
		t.Fatal(err)
	}
	paths, err := simTracePaths(in)
	if err != nil {
		t.Fatal(err)
	}
	resultsPath := os.Getenv("JED_SIM_RESULTS")
	if resultsPath == "" {
		resultsPath = filepath.Join(out, "go.results.jsonl")
	}
	results, err := os.OpenFile(resultsPath, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o644)
	if err != nil {
		t.Fatal(err)
	}
	defer results.Close()
	for _, path := range paths {
		res := simRunFile(path, out)
		fmt.Fprintln(results, res.json())
		if res.violation != "" {
			t.Errorf("%s: %s", path, res.violation)
		}
	}
}

func simTracePaths(in string) ([]string, error) {
	info, err := os.Stat(in)
	if err != nil {
		return nil, err
	}
	if info.IsDir() {
		paths, err := filepath.Glob(filepath.Join(in, "*.sim"))
		sort.Strings(paths)
		return paths, err
	}
	if strings.HasSuffix(in, ".sim") {
		return []string{in}, nil
	}
	data, err := os.ReadFile(in)
	if err != nil {
		return nil, err
	}
	var paths []string
	for _, line := range strings.Split(string(data), "\n") {
		if line = strings.TrimSpace(line); line != "" {
			paths = append(paths, line)
		}
	}
	return paths, nil
}

// --- trace parsing ------------------------------------------------------------------------------

type simStep struct {
	line   int
	kind   string
	sid    string
	mode   string
	sql    string
	params map[string]string
}

type simTrace struct {
	header map[string]string
	steps  []simStep
}

func simParse(text string) (simTrace, error) {
	tr := simTrace{header: map[string]string{}}
	for n, raw := range strings.Split(text, "\n") {
		line := strings.TrimRight(raw, "\r")
		if strings.TrimSpace(line) == "" {
			continue
		}
		if strings.HasPrefix(line, "#") {
			if k, v, ok := strings.Cut(strings.TrimSpace(line[1:]), ":"); ok {
				tr.header[strings.TrimSpace(k)] = strings.TrimSpace(v)
			}
			continue
		}
		fields := strings.Fields(line)
		st := simStep{line: n + 1, kind: fields[0], params: map[string]string{}}
		switch st.kind {
		case "open":
			if len(fields) != 3 {
				return tr, fmt.Errorf("line %d: open <sid> read|write", n+1)
			}
			st.sid, st.mode = fields[1], fields[2]
		case "on":
			if len(fields) < 3 {
				return tr, fmt.Errorf("line %d: on <sid> <sql>", n+1)
			}
			st.sid = fields[1]
			rest := strings.TrimSpace(line[len("on"):])
			st.sql = strings.TrimSpace(rest[len(st.sid):])
		case "commit", "rollback", "close":
			if len(fields) != 2 {
				return tr, fmt.Errorf("line %d: %s <sid>", n+1, st.kind)
			}
			st.sid = fields[1]
		case "fault", "crash":
			if len(fields) < 2 {
				return tr, fmt.Errorf("line %d: %s <kind> [k=v ...]", n+1, st.kind)
			}
			st.mode = fields[1]
			for _, kv := range fields[2:] {
				k, v, ok := strings.Cut(kv, "=")
				if !ok {
					return tr, fmt.Errorf("line %d: bad parameter %q", n+1, kv)
				}
				st.params[k] = v
			}
		case "clock":
			if len(fields) != 2 || !strings.HasPrefix(fields[1], "+") {
				return tr, fmt.Errorf("line %d: clock +<micros>", n+1)
			}
			st.params["delta"] = fields[1][1:]
		case "check", "reopen":
		default:
			return tr, fmt.Errorf("line %d: unknown step %q", n+1, st.kind)
		}
		tr.steps = append(tr.steps, st)
	}
	if tr.header["format"] != "simulation" {
		return tr, errors.New("missing `# format: simulation` header")
	}
	return tr, nil
}

func (st simStep) intParam(key string) int {
	n, _ := strconv.Atoi(st.params[key])
	return n
}

// simFaultOf builds the fault a `fault` step arms (simulation-testing.md §6.3).
func simFaultOf(st simStep) (*simFault, error) {
	switch st.mode {
	case "power_loss":
		return &simFault{kind: simPowerLoss, survive: st.intParam("survive"), tear: st.intParam("tear")}, nil
	case "process_crash":
		return &simFault{kind: simProcessCrash, issue: st.intParam("issue")}, nil
	case "io_error":
		switch st.params["op"] {
		case "write":
			return &simFault{kind: simIOWrite, p: st.intParam("p")}, nil
		case "sync":
			return &simFault{kind: simIOSync, nth: st.intParam("nth")}, nil
		}
	case "read_error":
		return &simFault{kind: simReadError, p: st.intParam("p")}, nil
	case "enospc":
		return &simFault{kind: simENOSPC}, nil
	}
	return nil, fmt.Errorf("line %d: unsupported fault %s %v", st.line, st.mode, st.params)
}

// --- the run ------------------------------------------------------------------------------------

type simResult struct {
	name           string
	steps          int
	violation      string
	violationStep  int
	transcriptHash uint64
	opsHash        uint64
}

func (r simResult) json() string {
	status := "pass"
	if r.violation != "" {
		status = "fail"
	}
	return fmt.Sprintf(`{"trace":%s,"core":"go","status":%q,"steps":%d,"violation":%s,"violation_step":%d,"transcript_hash":"%016x","ops_hash":"%016x"}`,
		simJSONString(r.name), status, r.steps, simJSONString(r.violation), r.violationStep, r.transcriptHash, r.opsHash)
}

// simJSONString encodes s as a JSON string (a violation message may hold any character).
func simJSONString(s string) string {
	b, _ := json.Marshal(s)
	return string(b)
}

// simRunFile runs one trace twice — the second run is the self-determinism check (§8.5) — and
// writes the first run's transcript (and, on a violation, the crash image) under out.
func simRunFile(path, out string) simResult {
	name := strings.TrimSuffix(filepath.Base(path), ".sim")
	res := simResult{name: name, violationStep: -1}
	data, err := os.ReadFile(path)
	if err != nil {
		res.violation = "read trace: " + err.Error()
		return res
	}
	tr, err := simParse(string(data))
	if err != nil {
		res.violation = "parse trace: " + err.Error()
		return res
	}
	first := newSimRunner(tr)
	if os.Getenv("JED_SIM_IMAGES") != "" {
		first.imagePrefix = filepath.Join(out, name+".go")
	}
	first.run()
	res.steps = len(tr.steps)
	res.transcriptHash = simFNV(first.transcript.String())
	res.opsHash = first.disk.ops
	_ = os.WriteFile(filepath.Join(out, name+".go.jsonl"), []byte(first.transcript.String()), 0o644)
	if first.violation != "" {
		res.violation = first.violation
		res.violationStep = first.violationStep
		for file, text := range first.diagnostics {
			_ = os.WriteFile(filepath.Join(out, name+".go."+file), []byte(text), 0o644)
		}
		if first.stack != "" {
			_ = os.WriteFile(filepath.Join(out, name+".go.stack.txt"), []byte(first.stack), 0o644)
		}
		if first.crashImage != nil {
			_ = os.WriteFile(filepath.Join(out, name+".go.crash.img"), first.crashImage, 0o644)
		}
		return res
	}
	second := newSimRunner(tr)
	second.run()
	switch {
	case second.violation != "":
		res.violation = "nondeterministic: the second run failed: " + second.violation
		res.violationStep = second.violationStep
	case second.transcript.String() != first.transcript.String():
		res.violation = "nondeterministic: transcripts differ between two runs" + simFirstDiff(first.transcript.String(), second.transcript.String())
	case second.disk.ops != first.disk.ops:
		res.violation = "nondeterministic: storage operation logs differ between two runs"
	}
	return res
}

func simFirstDiff(a, b string) string {
	al, bl := strings.Split(a, "\n"), strings.Split(b, "\n")
	for i := 0; i < len(al) && i < len(bl); i++ {
		if al[i] != bl[i] {
			return fmt.Sprintf(" (first difference:\n  %s\n  %s)", al[i], bl[i])
		}
	}
	return ""
}

func simFNV(s string) uint64 {
	h := fnv.New64a()
	h.Write([]byte(s))
	return h.Sum64()
}

type simSession struct {
	s     *Session
	write bool
	pin   uint64 // the version a read session pinned (§8.1: what it must keep seeing)
}

type simRunner struct {
	tr         simTrace
	seed       uint64
	pageSize   uint32
	cacheBytes int
	clock      int64

	// Handle settings from the header (simulation-testing.md §5, slice S3), applied at every open.
	workMem         int    // a session's work_mem; > 0 also gives the database a spill directory
	maxQueryMemory  int64  // a trace session's max_query_memory_bytes (the oracles' own reads are unlimited)
	maxStorageBytes int64  // the database's max_storage_bytes
	spillDir        string // the real scratch directory spill files go to; their bytes are not durable state

	disk     *simDisk
	db       *Database
	sessions map[string]*simSession
	armed    *simFault

	transcript strings.Builder

	// Oracle state (simulation-testing.md §8.1–8.2).
	history      map[uint64]map[string]bool // version → digests of every generation attempted at it
	version      uint64                     // the published version
	lastDigest   string                     // its digest
	floor        uint64                     // recovery may never return an older version
	maxAttempted uint64                     // ... nor a newer one than was ever attempted

	violation     string
	violationStep int
	crashImage    []byte
	stack         string // the goroutine stack of a panic violation

	lastDigestText string            // the text the most recent digest folded
	diagnostics    map[string]string // artifact name → contents, written on a violation
	imagePrefix    string            // when set, each recovery's image is written to <prefix>.step<N>.img
}

func newSimRunner(tr simTrace) *simRunner {
	seed, _ := strconv.ParseUint(tr.header["seed"], 10, 64)
	ps, _ := strconv.Atoi(tr.header["page_size"])
	if ps == 0 {
		ps = 256
	}
	cache, _ := strconv.Atoi(tr.header["cache_bytes"])
	clock, _ := strconv.ParseInt(tr.header["clock"], 10, 64)
	sector, _ := strconv.Atoi(tr.header["sector"])
	if sector <= 0 {
		sector = simSectorDefault
	}
	image, err := newSnapshot().ToImage(uint32(ps), 1)
	if err != nil {
		panic("an empty image always serializes: " + err.Error())
	}
	workMem, _ := strconv.Atoi(tr.header["work_mem"])
	maxQueryMemory, _ := strconv.ParseInt(tr.header["max_query_memory_bytes"], 10, 64)
	maxStorageBytes, _ := strconv.ParseInt(tr.header["max_storage_bytes"], 10, 64)
	spillDir := ""
	if workMem > 0 {
		spillDir = os.TempDir()
	}
	return &simRunner{
		tr:              tr,
		seed:            seed,
		pageSize:        uint32(ps),
		cacheBytes:      cache,
		clock:           clock,
		workMem:         workMem,
		maxQueryMemory:  maxQueryMemory,
		maxStorageBytes: maxStorageBytes,
		spillDir:        spillDir,
		disk:            newSimDisk(seed, sector, image),
		sessions:        map[string]*simSession{},
		history:         map[uint64]map[string]bool{},
		violationStep:   -1,
	}
}

func (r *simRunner) fail(step int, format string, args ...any) {
	if r.violation == "" {
		r.violation = fmt.Sprintf("step %d (line %d): ", step, r.tr.steps[step].line) + fmt.Sprintf(format, args...)
		r.violationStep = step
	}
}

func (r *simRunner) emit(format string, args ...any) {
	fmt.Fprintf(&r.transcript, format, args...)
	r.transcript.WriteByte('\n')
}

// open opens a Database over the simulated disk through the ordinary demand-paged loader — the
// path a reopening process takes, including validated-COW recovery (validated-cow.md §1).
func (r *simRunner) open() error {
	p, err := pagerFromStore(r.disk)
	if err != nil {
		return err
	}
	cache := r.cacheBytes
	if cache <= 0 {
		cache = defaultCacheBytes
	}
	e, err := loadEnginePaged(p, cacheLeaves(cache, p.pageSize))
	if err != nil {
		return err
	}
	e.path = simDiskPath
	e.spillDir = r.spillDir
	r.db = databaseOver(sharedCoreFromEngine(e))
	if r.maxStorageBytes > 0 {
		if err := r.db.SetMaxStorageBytes("main", r.maxStorageBytes); err != nil {
			return err
		}
	}
	return nil
}

func (r *simRunner) run() {
	if err := r.open(); err != nil {
		r.violation = "initial open: " + err.Error()
		return
	}
	r.version = r.db.Version()
	r.floor, r.maxAttempted = r.version, r.version
	d, ok := r.committedDigest()
	if !ok {
		r.violation = "initial digest failed"
		return
	}
	r.lastDigest = d
	r.addHistory(r.version, d)
	for i := range r.tr.steps {
		if !r.step(i) || r.violation != "" {
			return
		}
	}
}

func (r *simRunner) addHistory(v uint64, d string) {
	if r.history[v] == nil {
		r.history[v] = map[string]bool{}
	}
	r.history[v][d] = true
}

// step runs one trace step; false stops the run. A panic anywhere is a violation.
func (r *simRunner) step(i int) (cont bool) {
	defer func() {
		if p := recover(); p != nil {
			r.fail(i, "panic: %v", p)
			r.stack = string(debug.Stack())
			cont = false
		}
	}()
	st := r.tr.steps[i]
	switch st.kind {
	case "fault":
		f, err := simFaultOf(st)
		if err != nil {
			r.fail(i, "%v", err)
			return false
		}
		r.armed = f
		r.emit(`{"i":%d,"op":"fault","kind":%q}`, i, st.mode)
		return true
	case "crash":
		r.disk.beginStep(uint64(i), nil)
		if st.mode == "power" {
			r.disk.powerLoss(uint64(i), st.intParam("survive"), st.intParam("tear"))
		}
		return r.recover(i, "none")
	case "clock":
		delta, _ := strconv.ParseInt(st.params["delta"], 10, 64)
		r.clock += delta
		r.emit(`{"i":%d,"op":"clock"}`, i)
		return true
	}

	armed := r.armed
	r.armed = nil
	startVersion := r.version
	r.disk.beginStep(uint64(i), armed)
	switch st.kind {
	case "open":
		r.stepOpen(i, st)
	case "on":
		r.stepOn(i, st)
	case "commit":
		r.stepCommit(i, st)
	case "rollback", "close":
		r.stepEnd(i, st)
	case "check":
		r.stepCheck(i)
	case "reopen":
		if !r.stepReopen(i) {
			return false
		}
	}
	if r.violation != "" {
		return false
	}
	// A completed barrier made every earlier write durable: the generation published when the step
	// began can no longer be lost (§8.2).
	if r.disk.barrierOK && startVersion > r.floor {
		r.floor = startVersion
	}
	if armed == nil {
		return true
	}
	// Every faulted step ends the process; a power loss also discards the unsynced writes (§5).
	fired := r.disk.fired
	if fired == "" {
		fired = "end"
	}
	if armed.kind == simPowerLoss {
		r.disk.powerLoss(uint64(i), armed.survive, armed.tear)
	}
	return r.recover(i, fired)
}

func (r *simRunner) stepOpen(i int, st simStep) {
	if _, dup := r.sessions[st.sid]; dup {
		r.fail(i, "session %s already open", st.sid)
		return
	}
	var s *Session
	switch st.mode {
	case "read":
		s = r.db.ReadSession()
	case "write":
		for sid, ss := range r.sessions {
			if ss.write {
				r.fail(i, "open %s write while %s holds the writer gate", st.sid, sid)
				return
			}
		}
		s = r.db.WriteSession()
	default:
		r.fail(i, "unknown session mode %q", st.mode)
		return
	}
	s.SetRandomSource(SeededRandomSource(simDecide(r.seed, simLaneSession, uint64(i), 0, 0)))
	s.SetClockSource(func() int64 { return r.clock })
	if r.workMem > 0 {
		s.SetWorkMem(r.workMem)
	}
	if r.maxQueryMemory > 0 {
		s.SetMaxQueryMemoryBytes(r.maxQueryMemory)
	}
	r.sessions[st.sid] = &simSession{s: s, write: st.mode == "write", pin: s.Version()}
	r.emit(`{"i":%d,"op":"open","sid":%q,"version":%d}`, i, st.sid, s.Version())
}

func simCode(err error) string {
	var ee *EngineError
	if errors.As(err, &ee) {
		return ee.Code()
	}
	return "non-engine error: " + err.Error()
}

func (r *simRunner) stepOn(i int, st simStep) {
	ss, ok := r.sessions[st.sid]
	if !ok {
		r.emit(`{"i":%d,"op":"on","sid":%q,"skip":true}`, i, st.sid)
		return
	}
	n, affected, hash, cost, err := simQuery(ss.s, st.sql)
	if err != nil {
		code := simCode(err)
		if strings.HasPrefix(code, "non-engine") {
			r.fail(i, "%s", code)
			return
		}
		r.emit(`{"i":%d,"op":"on","sid":%q,"error":%q}`, i, st.sid, code)
		if code == "XX001" {
			r.fail(i, "corruption: a statement reported XX001: %v", err)
		}
		return
	}
	r.emit(`{"i":%d,"op":"on","sid":%q,"rows":%d,"affected":%d,"hash":"%016x","cost":%d}`, i, st.sid, n, affected, hash, cost)
}

// simQuery runs sql and folds its rendered rows, sorted (row order is not what this harness
// tests), into an FNV-1a hash.
func simQuery(s *Session, sql string) (n int, affected int64, hash uint64, cost int64, err error) {
	rows, err := s.Query(context.Background(), sql)
	if err != nil {
		return 0, 0, 0, 0, err
	}
	defer rows.Close()
	var rendered []string
	for rows.Next() {
		cells := make([]string, 0, len(rows.Row()))
		for _, v := range rows.Row() {
			text, err := s.Render(v)
			if err != nil {
				return 0, 0, 0, 0, err
			}
			cells = append(cells, text)
		}
		rendered = append(rendered, strings.Join(cells, "\x1f"))
	}
	if err := rows.Err(); err != nil {
		return 0, 0, 0, 0, err
	}
	sort.Strings(rendered)
	affected = -1
	if a, ok := rows.RowsAffected(); ok {
		affected = a
	}
	return len(rendered), affected, simFNV(strings.Join(rendered, "\x1e")), rows.Cost(), nil
}

// simDigestRelations is the catalog part of the logical digest (§8.1).
var simDigestRelations = []string{"jed_tables", "jed_columns", "jed_indexes", "jed_constraints", "jed_sequences"}

// digest is the logical digest of what s sees: the catalog relations plus every table's rows, all
// rendered and sorted, folded with FNV-1a. ok is false if any query failed (an aborted block).
func (r *simRunner) digest(s *Session) (string, bool) {
	// An armed read fault targets the trace's statements, not the oracle checking them.
	r.disk.oracle = true
	defer func() { r.disk.oracle = false }()
	// The oracle's own reads must not trip a trace session's memory limit.
	if limit := s.MaxQueryMemoryBytes(); limit > 0 {
		s.SetMaxQueryMemoryBytes(0)
		defer s.SetMaxQueryMemoryBytes(limit)
	}
	var b strings.Builder
	var tables []string
	r.lastDigestText = ""
	fold := func(sql string) bool {
		rows, err := s.Query(context.Background(), sql)
		if err != nil {
			r.lastDigestText = b.String() + sql + "\nERROR: " + err.Error() + "\n"
			return false
		}
		defer rows.Close()
		var rendered []string
		for rows.Next() {
			cells := make([]string, 0, len(rows.Row()))
			for _, v := range rows.Row() {
				text, err := s.Render(v)
				if err != nil {
					return false
				}
				cells = append(cells, text)
			}
			if sql == "SELECT * FROM jed_tables" {
				tables = append(tables, cells[0])
			}
			rendered = append(rendered, strings.Join(cells, "\x1f"))
		}
		if err := rows.Err(); err != nil {
			r.lastDigestText = b.String() + sql + "\nERROR: " + err.Error() + "\n"
			return false
		}
		sort.Strings(rendered)
		b.WriteString(sql)
		b.WriteByte('\n')
		b.WriteString(strings.Join(rendered, "\n"))
		b.WriteString("\n\n")
		return true
	}
	for _, rel := range simDigestRelations {
		if !fold("SELECT * FROM " + rel) {
			return "", false
		}
	}
	sort.Strings(tables)
	for _, t := range tables {
		if !fold(`SELECT * FROM "` + t + `"`) {
			return "", false
		}
	}
	r.lastDigestText = b.String()
	return fmt.Sprintf("%016x", simFNV(b.String())), true
}

// checkLive runs the live integrity checker with read faults suspended, like every oracle read.
func (r *simRunner) checkLive() error {
	r.disk.oracle = true
	defer func() { r.disk.oracle = false }()
	return simCheckLive(r.db)
}

func (r *simRunner) committedDigest() (string, bool) {
	rs := r.db.ReadSession()
	defer rs.Close()
	return r.digest(rs)
}

func (r *simRunner) stepCommit(i int, st simStep) {
	ss, ok := r.sessions[st.sid]
	if !ok {
		r.emit(`{"i":%d,"op":"commit","sid":%q,"skip":true}`, i, st.sid)
		return
	}
	delete(r.sessions, st.sid)
	base := r.version
	inflight, digestOK := r.digest(ss.s)
	inflightText := r.lastDigestText
	err := ss.s.Commit()
	now := r.db.Version()
	if err != nil {
		code := simCode(err)
		if strings.HasPrefix(code, "non-engine") {
			r.fail(i, "%s", code)
			return
		}
		r.emit(`{"i":%d,"op":"commit","sid":%q,"error":%q}`, i, st.sid, code)
		if code == "XX001" {
			r.fail(i, "corruption: commit reported XX001: %v", err)
			return
		}
		if now != base {
			r.fail(i, "a failed commit published version %d (was %d)", now, base)
			return
		}
		// The commit reached storage, so a crash may still recover its generation (§8.1).
		if digestOK && r.disk.writes > 0 {
			r.addHistory(base+1, inflight)
			r.maxAttempted = max(r.maxAttempted, base+1)
		}
		return
	}
	r.emit(`{"i":%d,"op":"commit","sid":%q,"version":%d}`, i, st.sid, now)
	switch now {
	case base:
		if digestOK && inflight != r.lastDigest {
			r.fail(i, "commit succeeded without publishing the transaction's changes")
		}
	case base + 1:
		if !digestOK {
			r.fail(i, "commit published version %d from a transaction whose reads failed", now)
			return
		}
		published, ok := r.committedDigest()
		if !ok || published != inflight {
			r.diagnostics = map[string]string{"before-commit.txt": inflightText, "after-commit.txt": r.lastDigestText}
			r.fail(i, "version %d does not contain what its transaction saw before commit", now)
			return
		}
		if err := r.checkLive(); err != nil {
			r.fail(i, "after commit: %v", err)
			return
		}
		r.addHistory(now, inflight)
		r.version, r.lastDigest = now, inflight
		r.maxAttempted = max(r.maxAttempted, now)
		r.floor = now // acknowledged under synchronous = on (§8.2)
	default:
		r.fail(i, "commit jumped from version %d to %d", base, now)
	}
}

func (r *simRunner) stepEnd(i int, st simStep) {
	ss, ok := r.sessions[st.sid]
	if !ok {
		r.emit(`{"i":%d,"op":%q,"sid":%q,"skip":true}`, i, st.kind, st.sid)
		return
	}
	delete(r.sessions, st.sid)
	if st.kind == "rollback" {
		if err := ss.s.Rollback(); err != nil {
			r.emit(`{"i":%d,"op":"rollback","sid":%q,"error":%q}`, i, st.sid, simCode(err))
			return
		}
	} else {
		// Snapshot isolation: a reader still sees exactly the version it pinned, however many
		// commits, reclamations, and page reuses happened since.
		if !ss.write {
			if d, ok := r.digest(ss.s); !ok || !r.history[ss.pin][d] {
				r.fail(i, "isolation: reader %s no longer sees version %d", st.sid, ss.pin)
			}
		}
		ss.s.Close()
	}
	r.emit(`{"i":%d,"op":%q,"sid":%q}`, i, st.kind, st.sid)
}

func (r *simRunner) stepCheck(i int) {
	d, ok := r.committedDigest()
	if !ok || d != r.lastDigest {
		r.fail(i, "a read session does not see the last committed version's contents")
		return
	}
	if err := r.checkLive(); err != nil {
		r.fail(i, "live integrity: %v", err)
		return
	}
	image := append([]byte(nil), r.disk.cache...)
	live, pages, free, err := simIntegrity(image, r.version)
	if err != nil {
		r.fail(i, "integrity: %v", err)
		return
	}
	r.emit(`{"i":%d,"op":"check","version":%d,"digest":%q,"live":%d,"pages":%d,"free":%d,"image":"%016x"}`,
		i, r.version, d, live, pages, free, simImageHash(image, pages, r.pageSize))
}

// stepReopen ends every session cleanly, closes the Database, and reopens it: the result must be
// exactly the last committed version.
func (r *simRunner) stepReopen(i int) bool {
	sids := make([]string, 0, len(r.sessions))
	for sid := range r.sessions {
		sids = append(sids, sid)
	}
	sort.Strings(sids)
	for _, sid := range sids {
		if ss := r.sessions[sid]; ss.write {
			_ = ss.s.Rollback()
		} else {
			ss.s.Close()
		}
	}
	r.sessions = map[string]*simSession{}
	if err := r.db.Close(); err != nil {
		r.fail(i, "close: %v", err)
		return false
	}
	r.disk.processDeath()
	if err := r.open(); err != nil {
		r.fail(i, "reopen failed: %v", err)
		return false
	}
	v := r.db.Version()
	d, ok := r.committedDigest()
	if v != r.version || !ok || d != r.lastDigest {
		r.fail(i, "a clean reopen returned version %d (digest %s), want version %d (digest %s)", v, d, r.version, r.lastDigest)
		return false
	}
	r.emit(`{"i":%d,"op":"reopen","version":%d,"digest":%q}`, i, v, d)
	return true
}

// recover abandons the crashed process — its sessions and Database — and opens the disk as a new
// process would, then checks the recovered generation against the history and the durability
// floor (§8.1–8.2) and the image against the integrity checker (§8.3).
func (r *simRunner) recover(i int, fired string) bool {
	r.sessions = map[string]*simSession{}
	r.db = nil
	r.disk.processDeath()
	image := append([]byte(nil), r.disk.cache...)
	if r.imagePrefix != "" {
		_ = os.WriteFile(fmt.Sprintf("%s.step%d.img", r.imagePrefix, i), image, 0o644)
	}
	if err := r.open(); err != nil {
		r.crashImage = image
		r.fail(i, "recovery: open failed: %v", err)
		return false
	}
	v := r.db.Version()
	d, ok := r.committedDigest()
	switch {
	case !ok:
		r.crashImage = image
		r.fail(i, "recovery: version %d is unreadable", v)
	case v < r.floor:
		r.crashImage = image
		r.fail(i, "durability: recovered version %d, but version %d was durable", v, r.floor)
	case v > r.maxAttempted:
		r.crashImage = image
		r.fail(i, "recovery: version %d was never attempted (latest attempted %d)", v, r.maxAttempted)
	case !r.history[v][d]:
		r.crashImage = image
		r.fail(i, "recovery: version %d has contents (digest %s) no transaction produced", v, d)
	}
	if r.violation != "" {
		return false
	}
	live, pages, free, err := simIntegrity(image, v)
	if err != nil {
		r.crashImage = image
		r.fail(i, "recovery integrity: %v", err)
		return false
	}
	r.version, r.lastDigest = v, d
	r.emit(`{"i":%d,"op":"crash","fired":%q,"recovered":%d,"digest":%q,"live":%d,"pages":%d,"free":%d,"image":"%016x"}`,
		i, fired, v, d, live, pages, free, simImageHash(image, pages, r.pageSize))
	return true
}

// simImageHash folds the logical image — the pages below the high-water — into FNV-1a 64 (§8.4).
// Preallocated tails past the high-water are host policy and excluded.
func simImageHash(image []byte, pages, pageSize uint32) uint64 {
	n := int(pages) * int(pageSize)
	if n > len(image) {
		n = len(image)
	}
	h := fnv.New64a()
	h.Write(image[:n])
	return h.Sum64()
}
